-- QA only; inject synthetic Auth session claims at TEST_CLAIMS. Everything rolls back.
begin;
create temp table qa_daily_test_results(name text,passed boolean) on commit drop;
create function pg_temp.qa_check(label text,condition boolean) returns void language plpgsql as $$begin
 if condition is not true then raise exception 'QA assertion failed: %',label; end if;
 insert into qa_daily_test_results values(label,true);
end $$;
do $$
declare claims jsonb:='{}'::jsonb /* TEST_CLAIMS */; label text; denied boolean; card uuid:=gen_random_uuid(); sale_key uuid:=gen_random_uuid(); purchase_key uuid:=gen_random_uuid(); request uuid; repeated uuid; count_request uuid; return_request uuid; doc uuid; body jsonb; header jsonb; sale_lines jsonb; before_report jsonb; after_report jsonb; before_count int; current_stock numeric; row record;
begin
 perform pg_temp.qa_check('private execution helper is not API-callable',not has_function_privilege('authenticated','pharmacy_qa_private.apply_employee_daily_operation(uuid,boolean)','execute'));
 perform pg_temp.qa_check('anonymous cannot call daily RPC',not has_function_privilege('anon','public.qa_employee_execute_workspace(text,jsonb,text,uuid)','execute'));
 for label in select unnest(array['support','unprivileged','anonymous']) loop
  perform set_config('request.jwt.claims',coalesce(claims->label,'{}'::jsonb)::text,true);
  denied:=false;begin perform public.qa_employee_execute_workspace('sale','[]',null,gen_random_uuid());exception when insufficient_privilege then denied:=true;end;
  perform pg_temp.qa_check(label||' cannot execute daily operations',denied);
  denied:=false;begin perform public.qa_save_workspace_product(null,'{}','[]',gen_random_uuid());exception when insufficient_privilege then denied:=true;end;
  perform pg_temp.qa_check(label||' cannot create product',denied);
 end loop;
 perform set_config('request.jwt.claims',(claims->'employee')::text,true);
 perform pg_temp.qa_check('synthetic employee session is live',public.qa_my_role()='employee');
 foreach label in array array['inventory_count','return_request','order_process','price_change'] loop
  denied:=false;begin perform public.qa_employee_execute_workspace(label,'[{}]',null,gen_random_uuid());exception when invalid_parameter_value then denied:=true;end;
  perform pg_temp.qa_check('direct sensitive operation denied: '||label,denied);
 end loop;
 body:=jsonb_build_object('name','QA transaction-only card','barcode','QA-TX-'||card,'active_ingredient','QA synthetic','strength','QA','dosage_form','QA','manufacturer','QA','category','QA category','active',true,'unit','box','reorder_level',1,'purchase_price',1.25,'sale_price',0,'parts_per_unit',10,'customer_visible',false,'sale_currency','USD');
 request:=public.qa_save_workspace_product(null,body,'[]',card);
 perform pg_temp.qa_check('employee creates a new product directly',request=card);
 perform pg_temp.qa_check('card replay is idempotent',public.qa_save_workspace_product(null,body,'[]',card)=card);
 denied:=false;begin perform public.qa_save_workspace_product(null,body,'[]',gen_random_uuid());exception when unique_violation then denied:=true;end;
 perform pg_temp.qa_check('duplicate primary barcode rejected',denied);
 denied:=false;begin perform public.qa_save_workspace_product(card,body||'{"sale_price":2}','[]',gen_random_uuid());exception when insufficient_privilege then denied:=true;end;
 perform pg_temp.qa_check('employee cannot edit an existing price',denied);
 denied:=false;begin perform public.qa_save_workspace_product(null,body||jsonb_build_object('barcode','QA-UNAPPROVED-'||card,'sale_price',2),'[]',gen_random_uuid());exception when insufficient_privilege then denied:=true;end;
 perform pg_temp.qa_check('unapproved initial price rejected',denied);
 denied:=false;begin perform public.qa_employee_execute_workspace('sale',jsonb_build_array(jsonb_build_object('product_id',card,'quantity',0.1)),null,gen_random_uuid());exception when invalid_parameter_value then denied:=true;end;
 perform pg_temp.qa_check('zero-price card cannot be sold',denied);
 perform set_config('request.jwt.claims',(claims->'manager')::text,true);
 perform pg_temp.qa_check('initial product purchase cost is retained for manager',(select (p->>'purchase_price')::numeric=1.25 from jsonb_array_elements(public.qa_workspace_snapshot()->'products') p where p->>'id'=card::text));
 request:=public.qa_save_workspace_product(card,body||'{"sale_price":2}','[]',gen_random_uuid());
 perform pg_temp.qa_check('manager can activate product price',request=card);
 perform set_config('request.jwt.claims',(claims->'employee')::text,true);
 select p into row from jsonb_array_elements(public.qa_workspace_snapshot()->'products') p where p->>'id'=card::text;
 perform pg_temp.qa_check('new product metadata is present',row.p->>'active_ingredient'='QA synthetic');
 perform pg_temp.qa_check('inline product category is retained',row.p->>'category'='QA category');
 perform pg_temp.qa_check('employee never receives purchase cost',not(row.p?'purchase_price'));
 header:=jsonb_build_object('supplier_id','00000000-0000-4000-8000-000000009001','invoice_number','QA-TX-'||card,'invoice_date',(now() at time zone 'Asia/Damascus')::date,'notes','transaction-only','paid_amount',0);
 body:=jsonb_build_array(jsonb_build_object('product_id',card,'quantity',2,'bonus',1,'unit_cost',1.25,'discount',0,'expiry','2027-12-31'));
 perform set_config('request.jwt.claims',(claims->'manager')::text,true);before_report:=public.qa_sandbox_report();
 perform set_config('request.jwt.claims',(claims->'employee')::text,true);
 request:=public.qa_employee_create_purchase(body,'USD',purchase_key,header);
 select sum(quantity) into current_stock from pharmacy_qa_private.batches where product_id=card;
 perform pg_temp.qa_check('purchase immediately receives quantity plus bonus',current_stock=3);
 perform pg_temp.qa_check('purchase is executed rather than queued',exists(select 1 from public.qa_employee_operations where id=request and status='approved' and payload->>'execution_mode'='employee_direct'));
 perform pg_temp.qa_check('invoice header is preserved',exists(select 1 from public.qa_employee_operations where id=request and payload->'purchase_header'=header));
 repeated:=public.qa_employee_create_purchase(body,'USD',purchase_key,header);
 perform pg_temp.qa_check('purchase retry returns original request',repeated=request);
 perform pg_temp.qa_check('purchase retry does not duplicate stock',(select sum(quantity)=3 from pharmacy_qa_private.batches where product_id=card));
 perform pg_temp.qa_check('purchase debt excludes free bonus',(select sum(l.amount)=2.5 from pharmacy_qa_private.ledger l join pharmacy_qa_private.documents d on d.id=l.document_id where d.product_id=card and l.kind='supplier_debt'));
 denied:=false;begin perform public.qa_employee_create_purchase(body,'USD',gen_random_uuid(),header);exception when unique_violation then denied:=true;end;
 perform pg_temp.qa_check('duplicate supplier invoice number rejected',denied);
 denied:=false;begin perform public.qa_employee_create_purchase(body,'USD',gen_random_uuid(),header||'{"paid_amount":1}');exception when invalid_parameter_value then denied:=true;end;
 perform pg_temp.qa_check('financial payment injection denied',denied);
 denied:=false;begin perform public.qa_employee_create_purchase(body,'USD',gen_random_uuid(),header||'{"invoice_date":"2020-01-01"}');exception when insufficient_privilege then denied:=true;end;
 perform pg_temp.qa_check('backdated purchase requires manager',denied);
 sale_lines:=jsonb_build_array(jsonb_build_object('product_id',card,'quantity',0.1));
 request:=public.qa_employee_execute_workspace('sale',sale_lines,null,sale_key);
 perform pg_temp.qa_check('sale directly deducts fractional quantity',(select sum(quantity)=2.9 from pharmacy_qa_private.batches where product_id=card));
 select d.id into doc from pharmacy_qa_private.documents d join public.qa_employee_operations o on o.id=d.request_id where o.payload->>'bundle_parent'=request::text;
 perform pg_temp.qa_check('sale uses server price and SYP settlement',exists(select 1 from pharmacy_qa_private.documents where id=doc and total=28 and currency='SYP'));
 perform pg_temp.qa_check('sale enters cash ledger atomically',exists(select 1 from pharmacy_qa_private.ledger where document_id=doc and kind='cash' and amount=28 and currency='SYP'));
 perform pg_temp.qa_check('sale retry is idempotent',public.qa_employee_execute_workspace('sale',sale_lines,null,sale_key)=request);
 denied:=false;begin perform public.qa_employee_execute_workspace('sale',jsonb_build_array(jsonb_build_object('product_id',card,'quantity',0.2)),null,sale_key);exception when invalid_parameter_value then denied:=true;end;
 perform pg_temp.qa_check('changed payload cannot reuse successful key',denied);
 select count(*) into before_count from pharmacy_qa_private.documents;
 denied:=false;begin perform public.qa_employee_execute_workspace('sale',jsonb_build_array(jsonb_build_object('product_id',card,'quantity',0.1),jsonb_build_object('product_id',card,'quantity',10000)),null,gen_random_uuid());exception when invalid_parameter_value then denied:=true;end;
 perform pg_temp.qa_check('overselling multi-line sale fails',denied);
 perform pg_temp.qa_check('failed sale rolls back all stock',(select sum(quantity)=2.9 from pharmacy_qa_private.batches where product_id=card));
 perform pg_temp.qa_check('failed sale creates no documents',(select count(*)=before_count from pharmacy_qa_private.documents));
 count_request:=public.qa_submit_workspace_bundle('inventory_count',jsonb_build_array(jsonb_build_object('product_id',card,'quantity',0,'expected_quantity',2.9)),null);
 perform pg_temp.qa_check('count remains pending',exists(select 1 from public.qa_employee_operations where id=count_request and status='pending'));
 perform pg_temp.qa_check('count does not change stock before approval',(select sum(quantity)=2.9 from pharmacy_qa_private.batches where product_id=card));
 denied:=false;begin perform public.qa_review_employee_operation(count_request,true);exception when insufficient_privilege then denied:=true;end;
 perform pg_temp.qa_check('employee cannot approve own count',denied);
 perform set_config('request.jwt.claims',(claims->'manager')::text,true);perform public.qa_review_employee_operation(count_request,false);
 perform set_config('request.jwt.claims',(claims->'employee')::text,true);
 return_request:=public.qa_submit_workspace_bundle('return_request',jsonb_build_array(jsonb_build_object('sale_id',doc,'quantity',0.1)),null);
 perform pg_temp.qa_check('return remains pending',exists(select 1 from public.qa_employee_operations where id=return_request and status='pending'));
 perform pg_temp.qa_check('return leaves stock unchanged until approved',(select sum(quantity)=2.9 from pharmacy_qa_private.batches where product_id=card));
 perform set_config('request.jwt.claims',(claims->'manager')::text,true);perform public.qa_review_employee_operation(return_request,true);
 perform pg_temp.qa_check('manager-approved return restores stock',(select sum(quantity)=3 from pharmacy_qa_private.batches where product_id=card));
 perform pg_temp.qa_check('sale and full return have zero net cash',(select sum(l.amount)=0 from pharmacy_qa_private.ledger l join pharmacy_qa_private.documents d on d.id=l.document_id where d.product_id=card and l.kind='cash'));
 perform set_config('request.jwt.claims',(claims->'support')::text,true);
 perform pg_temp.qa_check('support snapshot still contains only health and role',(select array_agg(k order by k)=array['health','role'] from jsonb_object_keys(public.qa_workspace_snapshot())k));
 perform pg_temp.qa_check('support cannot read requests',(select count(*)=0 from public.qa_sandbox_requests()));
end $$;
select jsonb_build_object('mode','transactional QA with synthetic Auth-session claims; not an HTTP/browser test','passed',count(*),'results',jsonb_agg(to_jsonb(r))) as result from qa_daily_test_results r;
rollback;
